// The channel between AnalyticsIOS (Dart) and AnalyticsFlutterPlugin (Swift), generated by Pigeon so
// that neither side hand-writes a method name or a map key. Regenerate after any change:
//
//   dart run pigeon --input pigeons/messages.dart
//
// The generated files are committed. The Android package has its own definition of the same shape
// (its config carries Android's push fields instead of the app group): each platform package owns
// its channel, as the federated layout intends.
import 'package:pigeon/pigeon.dart';

@ConfigurePigeon(
  PigeonOptions(
    dartOut: 'lib/src/messages.g.dart',
    dartOptions: DartOptions(),
    swiftOut: 'ios/funnelbase_flutter_ios/Sources/funnelbase_flutter_ios/Messages.g.swift',
    swiftOptions: SwiftOptions(),
    dartPackageName: 'funnelbase_flutter_ios',
  ),
)

/// `AnalyticsConfig` with `IosOptions` flattened into it.
class IosConfigMessage {
  IosConfigMessage({
    required this.apiKey,
    required this.endpoint,
    required this.flushIntervalSeconds,
    required this.flushBatchSize,
    required this.maxQueuedEvents,
    required this.sessionTimeoutMinutes,
    required this.trackApplicationLifecycle,
    required this.debugLogging,
    required this.registerApnsToken,
    this.appGroup,
  });

  String apiKey;
  String endpoint;
  int flushIntervalSeconds;
  int flushBatchSize;
  int maxQueuedEvents;
  double sessionTimeoutMinutes;
  bool trackApplicationLifecycle;
  bool debugLogging;
  String? appGroup;
  bool registerApnsToken;
}

class PushButtonMessage {
  PushButtonMessage({required this.id, required this.title, this.deepLink});

  String id;
  String title;
  String? deepLink;
}

class PushPayloadMessage {
  PushPayloadMessage({
    required this.deliveryId,
    required this.runId,
    required this.title,
    required this.body,
    required this.buttons,
    required this.data,
    this.imageUrl,
    this.deepLink,
    this.collapseKey,
  });

  String deliveryId;
  String runId;
  String title;
  String body;
  String? imageUrl;
  String? deepLink;
  String? collapseKey;
  List<PushButtonMessage> buttons;
  Map<String, String> data;
}

class PushTapMessage {
  PushTapMessage({required this.payload, this.actionId});

  PushPayloadMessage payload;
  String? actionId;
}

class TopicChoiceMessage {
  TopicChoiceMessage({
    required this.key,
    required this.name,
    required this.subscribed,
    required this.chosen,
    this.topicDescription,
  });

  String key;
  String name;
  /// The topic's `description`, renamed: Swift reserves `description` on every message class.
  String? topicDescription;
  bool subscribed;
  bool chosen;
}

/// One method per `AnalyticsPlatform` method, each onto the native SDK's own. Property maps hold
/// strings, numbers and booleans only — funnelbase_flutter has encoded dates and dropped nulls.
@HostApi()
abstract class AnalyticsHostApi {
  void initialize(IosConfigMessage config);

  void track(String eventName, Map<String, Object> properties);

  void screen(String screenName, Map<String, Object> properties);

  void identify(String userId, Map<String, Object> traits);

  void flush();

  void reset();

  void setPushToken(String token, String kind);

  void refreshPushToken();

  @async
  bool notificationsEnabled();

  String? registeredPushToken();

  @async
  bool requestNotificationPermission();

  void setTopic(String key, bool subscribed);

  /// Fails with a FlutterError whose code is `http` (details: the status), `network`,
  /// `malformed` or `not_initialized` — the four cases of `TopicsError`.
  @async
  List<TopicChoiceMessage> fetchTopics();

  /// Dart is listening: taps held since the process started are delivered now, and every later one
  /// as it happens.
  void pushTapsReady();
}

@FlutterApi()
abstract class AnalyticsFlutterApi {
  void onPushTapped(PushTapMessage tap);
}
